// Does the invoice reader read SAP invoices right — and when an invoice changes, does it
// keep reading through cosmetic changes and REFUSE (never misread) real ones?
//
// Owner's question, 2026-10-24: "What happens if the invoice is not exactly as you have
// received it right now?" This test is the answer, run instead of argued:
//   1. units        amounts, dates, amounts in words
//   2. DEMO PDFs    generated by demo-invoices.mjs, read through pdfjs end to end
//   3. real PDFs    (optional, --real <dir>) — the three SAP samples. Their values are
//                   never written here: only compared with each other and with the
//                   reader's own first reading. Prints counts, no customer data.
//   4. cosmetic     every PDF (demo + real) altered in ways a re-styled SAP form could:
//                   case, spacing, trailing colons, extra lines, jittered baselines, re-
//                   ordered address lines → must read EXACTLY the same
//   5. breaking     renamed labels, a wrong total, a missing bill, another form → must be
//                   REFUSED
//   6. money fuzz   change one digit of every printed amount, one at a time → the reader
//                   either refuses or reads the SAME money. Never different money.
//
// Run from the repo root:  node scripts/invoices/selftest-sap-invoice.mjs [--real <dir>]

import fs from 'node:fs'
import path from 'node:path'
import { readSapInvoice, toPaise, toIsoDate, wordsToPaise, formatRupees } from '../../src/invoices/lib/sapInvoice.js'
import { pdfToLines, groupLines } from '../../src/invoices/lib/pdfLines.js'
import { demoWorkshop, demoCounter, amountWords } from './demo-invoices.mjs'

const pdfjs = await import(new URL('../../node_modules/pdfjs-dist/legacy/build/pdf.mjs', import.meta.url).href)

let pass = 0, failed = 0
const ok = (name, cond, detail = '') => {
  if (cond) pass++
  else { failed++; console.log(`  FAIL  ${name}${detail ? ` — ${detail}` : ''}`) }
}
const section = (t) => console.log(`── ${t} ${'─'.repeat(Math.max(0, 60 - t.length))}`)
const clone = (x) => JSON.parse(JSON.stringify(x))
const money = (r) => r.ok ? JSON.stringify([r.total_paise, r.bills.map((b) => [b.bill_no, b.amount_paise])]) : null
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b)

// ── 1. units ─────────────────────────────────────────────────────────
section('units')
ok('toPaise 39,633.00', toPaise('39,633.00') === 3963300)
ok('toPaise Indian grouping 1,23,456.78', toPaise('1,23,456.78') === 12345678)
ok('toPaise trailing minus 0.43-', toPaise('0.43-') === -43)
ok('toPaise refuses 12.5 / text / 1,2,3.00', [toPaise('12.5'), toPaise('abc'), toPaise('1,2,3.00')].every((v) => v === null))
ok('toIsoDate 24.10.2026', toIsoDate('24.10.2026') === '2026-10-24')
ok('toIsoDate refuses 31.02.2026', toIsoDate('31.02.2026') === null)
ok('words: SIX THOUSAND FORTY EIGHT RUPEES ONLY', wordsToPaise('SIX THOUSAND FORTY EIGHT RUPEES ONLY') === 604800)
ok('words: with paise', wordsToPaise(': THIRTY ONE THOUSAND FOUR HUNDRED RUPEES AND ZERO PAISE ONLY') === 3140000)
ok('words: lakh', wordsToPaise('TWO LAKH SEVENTEEN THOUSAND RUPEES ONLY') === 21700000)
ok('words: refuses nonsense', wordsToPaise('SOME RUPEES ONLY') === null)
let roundTrip = true
for (const p of [0, 100, 1999, 604800, 3140050, 21700000, 999999999, 1234567801]) {
  if (wordsToPaise(amountWords(p, true)) !== p) roundTrip = false
}
ok('words: generator ↔ reader round trip (8 amounts up to ₹1.2 crore)', roundTrip)
ok('formatRupees ₹1,23,456.78', formatRupees(12345678) === '₹1,23,456.78')

// ── 2. DEMO PDFs end to end ─────────────────────────────────────────
section('DEMO PDFs through pdfjs')
const read = async (bytes) => {
  const lines = await pdfToLines(pdfjs, bytes)
  return { lines, r: readSapInvoice(lines) }
}
const docs = []   // [{ name, lines, r }] for the alteration tests
{
  const { lines, r } = await read(demoWorkshop())
  ok('workshop: read', r.ok, r.reason)
  ok('workshop: layout + form', r.layout === 'workshop' && r.sap_form === 'ZDBMF_COVERING_LETTER_001')
  ok('workshop: job card, date, customer, code, mobile, plate',
    r.doc_no === 'WTY57562627099001' && r.doc_date === '2026-10-24' && r.customer?.name === 'DEMO KRISHNA LOGISTICS'
    && r.customer?.sap_code === '900001' && r.customer?.mobile === '9000000001' && r.vehicle?.regn_no === 'GJ01ZZ0001', JSON.stringify(r))
  ok('workshop: mobile is the customer\'s, not the dealer\'s', r.customer?.mobile !== '7496970321')
  ok('workshop: two bills, total ₹40,665.00', r.bills?.length === 2 && r.total_paise === 4066500)
  ok('workshop: credit bills marked credit', r.bills?.every((b) => b.terms === 'credit'))
  ok('workshop: PAN + GSTIN from the bill pages', r.customer?.pan === 'AAAPZ9999Z' && r.customer?.gstin === '24AAAPZ9999Z1Z5')
  ok('workshop: seller GSTIN', r.seller_gstin === '24ABCFP3133C1ZV')
  if (r.ok) docs.push({ name: 'DEMO workshop', lines, r })
}
{
  const { r } = await read(demoWorkshop({ credit: false }))
  ok('workshop cash: bills marked cash', r.ok && r.bills.every((b) => b.terms === 'cash'), r.reason)
}
{
  const { lines, r } = await read(demoCounter())
  ok('counter: read', r.ok, r.reason)
  ok('counter: number, date, customer, code, mobile, terms',
    r.layout === 'counter_sale' && r.doc_no === 'MCI5756269900001' && r.doc_date === '2026-10-24'
    && r.customer?.name === 'DEMO SHIV SPARES' && r.customer?.sap_code === '900002' && r.customer?.mobile === '9000000002'
    && r.payment_terms === 'credit' && r.vehicle === null, JSON.stringify(r))
  ok('counter: one bill = the invoice, ₹31,400.00', r.bills?.length === 1 && r.bills[0].bill_no === r.doc_no && r.total_paise === 3140000)
  if (r.ok) docs.push({ name: 'DEMO counter', lines, r })
}
{
  const r = (await read(demoWorkshop({ totalOverride: 4066600 }))).r
  ok('workshop: summary total ≠ the bills → refused', !r.ok && /add up/.test(r.reason), r.reason)
  const r2 = (await read(demoCounter({ wordsOverride: amountWords(3140100, true) }))).r
  ok('counter: total ≠ amount in words → refused', !r2.ok && /words/.test(r2.reason), r2.reason)
  const doc = new (await import('jspdf')).jsPDF({ unit: 'pt' })
  doc.setProperties({ creator: 'Form ZSF_SOMETHING_ELSE EN' }); doc.text('INVOICE', 40, 40)
  const r3 = (await read(new Uint8Array(doc.output('arraybuffer')))).r
  ok('unknown SAP form → refused, naming the form', !r3.ok && /ZSF_SOMETHING_ELSE/.test(r3.reason), r3.reason)
  const blank = new (await import('jspdf')).jsPDF({ unit: 'pt' })
  const r4 = (await read(new Uint8Array(blank.output('arraybuffer')))).r
  ok('a PDF with no text (a scan) → refused as a scan', !r4.ok && /scan/.test(r4.reason), r4.reason)
}

// ── 3. real PDFs (optional) ─────────────────────────────────────────
const realAt = process.argv.indexOf('--real')
if (realAt > 0) {
  section('real SAP PDFs (values compared, never printed)')
  const dir = process.argv[realAt + 1]
  const files = fs.readdirSync(dir).filter((f) => /tax invoice\.pdf$/i.test(f))
  ok('real: found the samples', files.length > 0, dir)
  for (const f of files) {
    const { lines, r } = await read(new Uint8Array(fs.readFileSync(path.join(dir, f))))
    const label = `real #${docs.length - 1}`
    ok(`${label}: read`, r.ok, r.reason)
    if (!r.ok) continue
    ok(`${label}: the bills add up to the total`, r.bills.reduce((n, b) => n + b.amount_paise, 0) === r.total_paise)
    ok(`${label}: customer name, SAP code, 10-digit mobile`, !!r.customer.name && /^\d+$/.test(r.customer.sap_code) && /^\d{10}$/.test(r.customer.mobile ?? ''))
    ok(`${label}: PAN + GSTIN read and consistent`, !!r.customer.pan && r.customer.gstin?.slice(2, 12) === r.customer.pan)
    ok(`${label}: seller is PTB's GSTIN`, r.seller_gstin === '24ABCFP3133C1ZV')
    if (r.layout === 'workshop') {
      ok(`${label}: plate read`, !!r.vehicle?.regn_no)
      ok(`${label}: each bill's cash/credit agrees with its series (S = cash, R = credit)`,
        r.bills.every((b) => b.terms === ({ S: 'cash', R: 'credit' })[b.bill_no[2]]))
    } else {
      ok(`${label}: payment terms read`, !!r.payment_terms)
    }
    console.log(`  ${label}: ${r.layout}, ${r.bills.length} bill(s), ${lines.pages.length} page(s) — read`)
    docs.push({ name: label, lines, r })
  }
}

// ── 4. cosmetic changes must read the SAME ──────────────────────────
section('cosmetic changes → same reading')
const mapItems = (lines, f) => { const c = clone(lines); c.pages = c.pages.map((pg) => pg.map((l) => ({ ...l, items: l.items.map(f) }))); return c }
// Every label the reader looks for — restyling these is cosmetic; values are left alone.
const LABELS = new Set(['DLR INVOICE NO', 'INVOICE DATE', 'DEALER REF NO', 'SAP INVOICE NO', 'CUSTOMER PAN', 'GSTIN',
  'PAYMENT TERMS', 'Grand Total(INR)', 'AMOUNT IN WORDS', 'INVOICE SUMMARY', 'JOB CARD NO', 'ORDER NUMBER', 'CUSTOMER',
  'REGN. NO', 'BILL NO', 'GRAND TOTAL (INR)', 'INVOICE NO', 'ORDER TYPE', 'VEHICLE MODEL', 'CHASSIS NO', 'ENGINE NO',
  'GSTIN / UIN', 'CASH BILL', 'CREDIT BILL'])
const isLabelish = (s) => LABELS.has(s.trim())
const cosmetic = {
  'labels in Title Case': (L) => mapItems(L, (s) => isLabelish(s) ? s.toLowerCase().replace(/\b[a-z]/g, (c) => c.toUpperCase()) : s),
  'labels with a trailing colon': (L) => mapItems(L, (s) => isLabelish(s) ? `${s}:` : s),
  'double spaces inside labels': (L) => mapItems(L, (s) => isLabelish(s) ? s.replace(/ /g, '  ') : s),
  'padding around every item': (L) => mapItems(L, (s) => ` ${s}  `),
  'an extra line after every line': (L) => { const c = clone(L); c.pages = c.pages.map((pg) => pg.flatMap((l) => [l, { y: l.y - 3, items: ['Thank you for your business'] }])); return c },
  'a new line at the top of each page': (L) => { const c = clone(L); c.pages = c.pages.map((pg) => [{ y: 999, items: ['GST registered dealer — Ashok Leyland'] }, ...pg]); return c },
}
for (const d of docs) {
  for (const [name, f] of Object.entries(cosmetic)) {
    const r = readSapInvoice(f(d.lines))
    ok(`${d.name}: ${name}`, r.ok && same({ ...r, checks: 0 }, { ...d.r, checks: 0 }), r.ok ? 'read differently' : r.reason)
  }
}
// Baseline jitter + item order at the pdfjs level (the grouping step itself).
{
  const items = [
    { str: 'TOTAL', transform: [1, 0, 0, 1, 300, 100.0] }, { str: 'JOB CARD NO', transform: [1, 0, 0, 1, 40, 200.9] },
    { str: ': X1', transform: [1, 0, 0, 1, 120, 199.2] }, { str: '9.00', transform: [1, 0, 0, 1, 400, 101.5] },
  ]
  const g = groupLines(items)
  ok('grouping: baselines within 2 pt join one line, left to right, top line first',
    same(g.map((l) => l.items), [['JOB CARD NO', ': X1'], ['TOTAL', '9.00']]), JSON.stringify(g))
}

// ── 5. breaking changes must be REFUSED ─────────────────────────────
section('breaking changes → refused')
const renameLabel = (from, to) => (L) => mapItems(L, (s) => s.trim() === from ? to : s)
const breaking = {
  workshop: {
    'JOB CARD NO renamed JOB CARD NUMBER': renameLabel('JOB CARD NO', 'JOB CARD NUMBER'),
    'GRAND TOTAL (INR) renamed NET PAYABLE': renameLabel('GRAND TOTAL (INR)', 'NET PAYABLE'),
    'CUSTOMER renamed PARTY': renameLabel('CUSTOMER', 'PARTY'),
    'the summary page removed': (L) => ({ ...clone(L), pages: clone(L).pages.slice(1) }),
    "the last bill's pages removed": (L) => {
      const c = clone(L); const last = L.pages.length - 1
      const no = c.pages[last].flatMap((l) => l.items).find((s) => /^[A-Z]{3}\d{10,}$/.test(s.trim()))
      c.pages = c.pages.filter((pg, i) => i === 0 || !pg.some((l) => l.items.some((s) => s.trim() === no)))
      return c
    },
    "a bill's own pages print a different grand total": (L) => {
      const c = clone(L)
      for (const pg of c.pages.slice(1)) for (const l of pg) {
        const i = l.items.findIndex((s) => s.trim() === 'GRAND TOTAL (INR)')
        if (i < 0) continue
        const j = l.items.findLastIndex((s) => toPaise(s) != null)
        l.items[j] = formatRupees(toPaise(l.items[j]) + 100).slice(1)
        return c
      }
      return c
    },
    "a bill's pages carry another customer code": (L) => {
      const c = clone(L)
      const last = c.pages[c.pages.length - 1]
      for (const l of last) l.items = l.items.map((s) => s.replace(/\[(\d+)\]/, (_, d) => `[${String((+d + 1))}]`))
      return c
    },
    'another SAP form name': (L) => ({ ...clone(L), creator: 'Form ZDBMF_COVERING_LETTER_002 EN' }),
    'no Creator at all (re-saved by another program)': (L) => ({ ...clone(L), creator: 'Microsoft Word' }),
  },
  counter_sale: {
    'DLR INVOICE NO renamed INVOICE NUMBER': renameLabel('DLR INVOICE NO', 'INVOICE NUMBER'),
    'Grand Total(INR) renamed Net Amount': renameLabel('Grand Total(INR)', 'Net Amount'),
    'AMOUNT IN WORDS removed': renameLabel('AMOUNT IN WORDS', 'REMARKS'),
    'another SAP form name': (L) => ({ ...clone(L), creator: 'Form ZSF_RETAIL_INVOICE_GST_V2 EN' }),
  },
}
for (const d of docs) {
  for (const [name, f] of Object.entries(breaking[d.r.layout])) {
    const r = readSapInvoice(f(d.lines))
    ok(`${d.name}: ${name}`, !r.ok, 'was read anyway')
  }
}

// ── 6. money fuzz: one changed digit never yields different money ────
section('money fuzz — refuse or same money, never different money')
for (const d of docs) {
  let tried = 0, refused = 0, sameMoney = 0, wrong = 0
  d.lines.pages.forEach((pg, p) => pg.forEach((l, li) => l.items.forEach((s, ii) => {
    if (toPaise(s) == null) return
    const m = /\d(?=[\d,]*\.\d\d-?\s*$)/.exec(s)   // the last whole-rupee digit
    if (!m) return
    const c = clone(d.lines)
    c.pages[p][li].items[ii] = s.slice(0, m.index) + String((+m[0] + 1) % 10) + s.slice(m.index + 1)
    const r = readSapInvoice(c)
    tried++
    if (!r.ok) refused++
    else if (money(r) === money(d.r)) sameMoney++
    else wrong++
  })))
  const line = `${d.name}: ${tried} amounts changed one at a time — ${refused} refused, ${sameMoney} same money, ${wrong} different money`
  console.log(`  ${line}`)
  ok(line, wrong === 0 && tried > 0)
}

console.log(`\n${pass} passed, ${failed} failed`)
process.exit(failed ? 1 : 0)
